from rdkit import Chem
from rdkit.Chem import AllChem
import numpy as np
rw=Chem.RWMol(); coords={}; names={}
def atom(name, elem='C', xy=(0,0), z=0.0):
    idx=rw.AddAtom(Chem.Atom(elem)); coords[idx]=np.array([xy[0],-xy[1],z],dtype=float)*0.025; names[name]=idx; return idx
P={'A':(291,182),'B':(291,303),'L1':(176,146),'L2':(105,244),'L3':(176,342),'C':(395,123),'D':(499,183),'G':(499,303),'H':(395,363),'E':(615,148),'K':(682,244),'F':(612,339),'V':(683,47),'W':(799,86),'R':(799,207),'T':(870,304),'U':(799,397),'S':(682,363),'MA':(291,110),'IP':(158,392),'IPM1':(115,448),'IPM2':(207,448),'ME':(579,105),'MT':(923,304),'CARB':(638,414),'O1':(649,459),'O2':(680,397)}
for n,p in P.items(): atom(n,'O' if n in ('O1','O2') else 'C',p)
bonds=[('A','L1',1),('L1','L2',1),('L2','L3',1),('L3','B',1),('B','A',1),('A','C',1),('C','D',1),('D','G',1),('G','H',1),('H','B',1),('D','E',1),('E','K',1),('K','F',1),('F','G',2),('E','V',1),('V','W',1),('W','R',1),('R','K',1),('K','S',1),('S','U',1),('U','T',1),('T','R',1),('A','MA',1),('L3','IP',1),('IP','IPM1',1),('IP','IPM2',1),('E','ME',1),('T','MT',1),('F','CARB',1),('CARB','O1',2),('CARB','O2',1)]
for a,b,o in bonds: rw.AddBond(names[a],names[b],Chem.BondType.SINGLE if o==1 else Chem.BondType.DOUBLE)
m=rw.GetMol(); Chem.SanitizeMol(m)
conf=Chem.Conformer(m.GetNumAtoms())
for i,v in coords.items(): conf.SetAtomPosition(i,tuple(v))
m.AddConformer(conf)
m=Chem.AddHs(m,addCoords=True)
# implicit Hs stereochem opposite the shown methyl/isopropyl wedge
for center,sign in [('A',+1),('L3',-1),('E',+1),('T',-1)]:
 ci=names[center]; hs=[a.GetIdx() for a in m.GetAtomWithIdx(ci).GetNeighbors() if a.GetAtomicNum()==1]; assert len(hs)==1,(center,hs)
 p=np.array(m.GetConformer().GetAtomPosition(ci)); m.GetConformer().SetAtomPosition(hs[0],tuple(p+np.array([0,0,-sign*0.025])))
# Explicit stereohydrogens as wedged/hash bonds
for center,xy,sign in [('B',(291,380),-1),('D',(480,118),+1),('R',(862,180),-1)]:
 ci=names[center]; hs=[a.GetIdx() for a in m.GetAtomWithIdx(ci).GetNeighbors() if a.GetAtomicNum()==1]; assert len(hs)==1,(center,hs)
 xyz=np.array([xy[0],-xy[1],0.0])*0.025; xyz[2]=sign*0.025; m.GetConformer().SetAtomPosition(hs[0],tuple(xyz))
# Wedge/hash heavy atom endpoints
for name,sign in [('MA',+1),('ME',+1),('IP',-1),('MT',-1)]:
 i=names[name]; q=np.array(m.GetConformer().GetAtomPosition(i)); q[2]=sign*0.025; m.GetConformer().SetAtomPosition(i,tuple(q))
Chem.AssignAtomChiralTagsFromStructure(m,confId=0,replaceExistingTags=True)
Chem.AssignStereochemistry(m,cleanIt=True,force=True)
print('stereo assigned:')
for a in m.GetAtoms():
 if a.HasProp('_CIPCode'): print(a.GetIdx(),a.GetProp('_CIPCode'),next((n for n,i in names.items() if i==a.GetIdx()),''))
print('smiles',Chem.MolToSmiles(Chem.RemoveHs(m),isomericSmiles=True))
m.RemoveAllConformers()
params=AllChem.ETKDGv3(); params.randomSeed=280; params.maxAttempts=1000
res=AllChem.EmbedMolecule(m,params); print('embed',res)
if res<0:
 params.useRandomCoords=True; res=AllChem.EmbedMolecule(m,params); print('retry',res)
if res<0: raise SystemExit('embedding failed')
props=AllChem.MMFFGetMoleculeProperties(m)
if props:
 ff=AllChem.MMFFGetMoleculeForceField(m,props); print('MMFF',ff.Minimize(maxIts=2000))
Chem.AssignStereochemistry(m,cleanIt=True,force=True)
for a in m.GetAtoms():
 if a.HasProp('_CIPCode'): print('final',a.GetIdx(),a.GetProp('_CIPCode'),next((n for n,i in names.items() if i==a.GetIdx()),''))
conf=m.GetConformer()
with open('answer.xyz','w') as f:
 f.write(f'{m.GetNumAtoms()}\n3D structure generated from mol_0280.png\n')
 for a in m.GetAtoms():
  x,y,z=conf.GetAtomPosition(a.GetIdx()); f.write(f'{a.GetSymbol():2s} {x: .8f} {y: .8f} {z: .8f}\n')
print('wrote',m.GetNumAtoms())
